from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]

def read(path): return (ROOT/path).read_text(encoding='utf-8')
def write(path,text): (ROOT/path).write_text(text,encoding='utf-8')
def replace_once(path,old,new):
    text=read(path)
    if text.count(old)!=1:
        raise SystemExit(f'{path}: expected one anchor, found {text.count(old)}: {old[:100]!r}')
    write(path,text.replace(old,new,1))

def replace_all(path,old,new,min_count=1):
    text=read(path);count=text.count(old)
    if count<min_count: raise SystemExit(f'{path}: expected >= {min_count} anchors, found {count}: {old!r}')
    write(path,text.replace(old,new))

