# New auto-discovered logic contract.
write('scripts/check-hunger-food.mjs',"""import assert from 'node:assert/strict';
import {ITEMS} from '../src/items.js';
import {addHungerExhaustion,attackExhaustion,consumeFood,createHungerState,damageExhaustion,jumpExhaustion,movementExhaustion,stepHunger} from '../src/hunger-rules.js';
import {furnaceFuelTicks,smeltingRecipeFor,tickFurnace} from '../src/smelting.js';

const close=(actual,expected,epsilon=1e-9)=>assert.ok(Math.abs(actual-expected)<=epsilon,`${actual} != ${expected}`);
for(const [id,nutrition,saturationModifier] of [['apple',4,.3],['bread',5,.6],['raw_beef',3,.3],['cooked_beef',8,.8],['raw_mutton',2,.3],['cooked_mutton',6,.8],['raw_porkchop',3,.3],['cooked_porkchop',8,.8],['raw_chicken',2,.3],['cooked_chicken',6,.6],['rotten_flesh',4,.1]])assert.deepEqual(ITEMS[id].food,{nutrition,saturationModifier});
let eaten=consumeFood(createHungerState({food:10,saturation:0}),ITEMS.bread.food);assert.equal(eaten.consumed,true);assert.equal(eaten.state.food,15);assert.equal(eaten.state.saturation,6);
assert.equal(consumeFood(createHungerState({food:20,saturation:5}),ITEMS.apple.food).consumed,false);
eaten=consumeFood(createHungerState({food:18,saturation:1}),ITEMS.apple.food);assert.equal(eaten.state.food,20);close(eaten.state.saturation,3.4);
let state=addHungerExhaustion(createHungerState({food:20,saturation:2}),4.1),step=stepHunger(state,{dt:.05,hp:20});assert.equal(step.state.food,20);assert.equal(step.state.saturation,1);close(step.state.exhaustion,.1);
assert.equal(movementExhaustion(10,{sprinting:true}),1);assert.equal(movementExhaustion(10,{swimming:true}),.1);assert.equal(jumpExhaustion(),.05);assert.equal(jumpExhaustion({sprinting:true}),.2);assert.equal(attackExhaustion(),.1);assert.equal(damageExhaustion(),.1);
step=stepHunger(createHungerState({food:20,saturation:5}),{dt:.5,hp:18});close(step.heal,5/6);assert.equal(step.damage,0);assert.equal(step.state.saturation,4);close(step.state.exhaustion,1);
step=stepHunger(createHungerState({food:18,saturation:0}),{dt:4,hp:18});assert.equal(step.heal,1);assert.equal(step.state.food,17);close(step.state.exhaustion,2);
step=stepHunger(createHungerState({food:0,saturation:0}),{dt:4,hp:2});assert.equal(step.damage,1);step=stepHunger(createHungerState({food:0,saturation:0}),{dt:8,hp:1});assert.equal(step.damage,0,'normal starvation floor must not kill the player');
for(const [input,output] of [['raw_beef','cooked_beef'],['raw_mutton','cooked_mutton'],['raw_porkchop','cooked_porkchop'],['raw_chicken','cooked_chicken']]){const recipe=smeltingRecipeFor(input);assert.equal(recipe.output,output);assert.equal(recipe.cookTicks,200);assert.equal(recipe.experience,.35);const result=tickFurnace({slots:[{id:input,count:1},{id:'coal',count:1},null]},200);assert.equal(result.state.slots[2].id,output);assert.equal(result.smelted,1);}
assert.equal(furnaceFuelTicks('coal'),1600);
console.log('hunger/food rules + canonical food registry + Furnace meat cooking: PASS');
""")

# Browser integration: eat, reject at full hunger, fast regen, starvation floor, and persisted v9 state.
write('tests/e2e/hunger-food.spec.mjs',"""import {test,expect} from '@playwright/test';
import {createSingleplayerWorld} from './helpers/world-flow.mjs';
async function runCommand(page,text){await page.evaluate(()=>window.dispatchEvent(new KeyboardEvent('keydown',{code:'Slash',bubbles:true})));await expect(page.locator('#chat-input-wrap')).not.toHaveClass(/hidden/);await page.locator('#chat-input').fill(text);await page.locator('#chat-input').press('Enter');await expect(page.locator('#chat-input-wrap')).toHaveClass(/hidden/);}
async function key(page,code){await page.evaluate(code=>window.dispatchEvent(new KeyboardEvent('keydown',{code,bubbles:true})),code);}
async function savedWorlds(page){return page.evaluate(()=>new Promise((resolve,reject)=>{const request=indexedDB.open('minecraft-web-by-ai',1);request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,tx=db.transaction('worlds','readonly'),getAll=tx.objectStore('worlds').getAll();getAll.onerror=()=>reject(getAll.error);getAll.onsuccess=()=>{const value=getAll.result;db.close();resolve(value);};};}));}
test('singleplayer food consumes into Java-style hunger state and persists schema v9',async({page})=>{const pageErrors=[],consoleErrors=[];page.on('pageerror',error=>pageErrors.push(error.message));page.on('console',message=>{if(message.type()==='error')consoleErrors.push(message.text());});await page.goto('/?e2e=1');await createSingleplayerWorld(page,{name:'CI Hunger Food',seed:'ci-hunger-food-2026',mode:'survival',prompt:'平原'});await runCommand(page,'/give bread 2');await key(page,'KeyE');const bread=page.locator('#inventory-grid [data-inv-index]').filter({has:page.locator('img[alt="面包"]')}).first();await expect(bread).toBeVisible();await bread.click({modifiers:['Shift']});await key(page,'Escape');await page.evaluate(()=>globalThis.__minecraftE2E.setPlayerVitals({hp:20,food:10,saturation:0,exhaustion:0,timer:0}));const canvas=page.locator('#game-canvas');await canvas.click({position:{x:8,y:8}});await expect.poll(()=>page.evaluate(()=>document.pointerLockElement?.id||null),{timeout:5_000}).toBe('game-canvas');await canvas.dispatchEvent('mousedown',{button:2,bubbles:true});await expect.poll(()=>page.evaluate(()=>globalThis.__minecraftE2E.playerVitals()),{timeout:3_000}).toMatchObject({food:15,saturation:6});await expect(page.locator('#hotbar [data-hotbar-index="0"]')).toHaveAttribute('title','面包');await expect(page.locator('#hotbar [data-hotbar-index="0"] .slot-count')).toHaveText('1');await page.evaluate(()=>globalThis.__minecraftE2E.setPlayerVitals({hp:20,food:20,saturation:5,exhaustion:0,timer:0}));await canvas.dispatchEvent('mousedown',{button:2,bubbles:true});await expect(page.locator('#toast')).toContainText('饥饿值已满');await expect(page.locator('#hotbar [data-hotbar-index="0"] .slot-count')).toHaveText('1');await page.evaluate(()=>globalThis.__minecraftE2E.setPlayerVitals({hp:18,food:20,saturation:5,exhaustion:0,timer:.49}));await expect.poll(async()=>Number((await page.evaluate(()=>globalThis.__minecraftE2E.playerVitals())).hp),{timeout:2_000}).toBeGreaterThan(18);await page.evaluate(()=>globalThis.__minecraftE2E.setPlayerVitals({hp:2,food:0,saturation:0,exhaustion:0,timer:3.95}));await expect.poll(async()=>Number((await page.evaluate(()=>globalThis.__minecraftE2E.playerVitals())).hp),{timeout:2_000}).toBe(1);await page.waitForTimeout(250);expect((await page.evaluate(()=>globalThis.__minecraftE2E.playerVitals())).hp).toBe(1);await key(page,'Escape');await expect(page.locator('#pause-menu')).toHaveClass(/active/);await expect.poll(async()=>{const record=(await savedWorlds(page)).find(world=>world.name==='CI Hunger Food');if(!record)return null;return{version:record.version,terrainVersion:record.terrainVersion,hunger:record.player?.hunger,saturation:record.player?.saturation,hasExhaustion:Number.isFinite(record.player?.exhaustion),hasTimer:Number.isFinite(record.player?.foodTickTimer)};},{timeout:10_000}).toEqual({version:9,terrainVersion:3,hunger:0,saturation:0,hasExhaustion:true,hasTimer:true});expect(pageErrors).toEqual([]);expect(consoleErrors).toEqual([]);});
""")

